def json_schema_to_model(name: str, schema: dict | None) -> type[BaseModel]:
    """把 OpenAI function parameters 转成 Pydantic 模型，给 StructuredTool 用。"""
    schema = schema or {}
    props = schema.get("properties") or {}
    required = set(schema.get("required") or [])
    fields: dict[str, Any] = {}
    for key, spec in props.items():
        spec = spec or {}
        py_type = _JSON_TYPES.get(spec.get("type"), str)
        description = spec.get("description") or ""
        if key in required:
            fields[key] = (py_type, Field(description=description))
        else:
            fields[key] = (py_type | None, Field(default=None, description=description))
    model_name = "".join(part.capitalize() for part in name.split("_")) + "Args"
    if not fields:
        return create_model(model_name)
    return create_model(model_name, **fields)

def spec_to_langchain_tool(spec: ToolSpec, bound: dict[str, Callable[..., Any]]):
    from langchain_core.tools import StructuredTool

    fn = spec.fn or bound.get(spec.name)
    schema = spec.parameters or {}
    model = json_schema_to_model(spec.name, schema)

    async def _run(**kwargs: Any) -> str:
        if fn is None:
            return f"未知工具: {spec.name}"
        cleaned = {key: value for key, value in kwargs.items() if value is not None}
        result = fn(**cleaned)
        return await result if isawaitable(result) else result

    return StructuredTool.from_function(
        name=spec.name,
        description=spec.description,
        coroutine=_run,
        args_schema=model,
    )

async def _run(**kwargs: Any) -> str:
        if fn is None:
            return f"未知工具: {spec.name}"
        cleaned = {key: value for key, value in kwargs.items() if value is not None}
        result = fn(**cleaned)
        return await result if isawaitable(result) else result

def build_langchain_tools(
    user_id: str, session_factory, groups: list[str] | None = None, *,
    read_only: bool = False,
):
    bound = registry.bind(bind_user_tools(user_id, session_factory))
    return [
        spec_to_langchain_tool(spec, bound) for spec in registry.resolve(groups)
        if not read_only or spec.parallel_safe
    ]

def settings_for_role(settings: Settings, role: str) -> Settings:
    names = {
        "classifier": settings.classifier_model,
        "plan": settings.plan_model,
        "reflection": settings.reflection_model or settings.plan_model,
        "title": settings.title_model or settings.classifier_model,
    }
    return settings.model_copy(update={"llm_model": names.get(role) or settings.llm_model})

def set_plan_streamer(fn: PlanStreamer | None) -> None:
    global _injected_streamer
    _injected_streamer = fn

def set_plan_fn(fn: PlanFn | None) -> None:
    global _injected_plan
    _injected_plan = fn

def plan_available(settings: Settings) -> bool:
    return settings.plan_execute_enabled and bool(
        _injected_streamer or _injected_plan or settings.llm_api_key
    )

def build_plan_tool_list() -> str:
    return "\n".join(
        f"- {spec.name}: {spec.description}" for spec in registry.resolve()
    ) + "\n- none: 根据已有结果分析、总结，不调用工具"

def parse_plan_payload(raw: str, fallback_goal: str = "") -> ExecutionPlan:
    content = re.sub(r"```(?:json)?\s*", "", (raw or "").strip()).strip()
    try:
        data = json.loads(content)
    except json.JSONDecodeError:
        match = re.search(r"\{.*\}", content, re.DOTALL)
        if not match:
            raise ValueError("Plan JSON 解析失败")
        data = json.loads(match.group())
    if not isinstance(data, dict) or not isinstance(data.get("steps"), list):
        raise ValueError("Plan 无步骤")
    steps = []
    for index, item in enumerate(data["steps"], 1):
        tool = str(item.get("tool") or "none")
        if tool != "none" and registry.get(tool) is None:
            raise ValueError(f"Plan 包含未注册工具: {tool}")
        steps.append(PlanStep(
            step=int(item.get("step") or index),
            action=str(item.get("action") or "").strip(),
            tool=tool,
            depends_on=[int(dep) for dep in (item.get("depends_on") or [])],
        ))
    if not steps or any(not step.action for step in steps):
        raise ValueError("Plan 无有效步骤")
    topological_batches(steps)
    return ExecutionPlan(str(data.get("goal") or fallback_goal)[:200], steps)

def topological_batches(steps: list[PlanStep]) -> list[list[PlanStep]]:
    ids = {step.step for step in steps}
    if len(ids) != len(steps) or any(step.step <= 0 for step in steps):
        raise ValueError("计划步骤编号必须唯一且为正数")
    if any(dep not in ids for step in steps for dep in step.depends_on):
        raise ValueError("计划依赖了不存在的步骤")
    completed: set[int] = set()
    remaining = list(steps)
    batches = []
    while remaining:
        ready = [step for step in remaining if set(step.depends_on) <= completed]
        if not ready:
            raise ValueError("计划存在循环依赖")
        batches.append(ready)
        completed.update(step.step for step in ready)
        remaining = [step for step in remaining if step not in ready]
    return batches

async def generate_plan(message: str, settings: Settings) -> ExecutionPlan:
    from app.ai_service.thinking import complete_thinking_for

    async with asyncio.timeout(settings.plan_timeout):
        if _injected_plan:
            return await _injected_plan(message)
        raw = await _complete(
            build_plan_prompt(message), settings, "plan", settings.plan_timeout,
            complete_thinking_for("plan", settings),
        )
        return parse_plan_payload(raw, visible_question(message))

def _safe_batches(batch, limit):
    reads = []
    for step in batch:
        spec = registry.get(step.tool)
        if step.tool == "none" or (spec and spec.parallel_safe):
            reads.append(step)
            if len(reads) >= limit:
                yield reads
                reads = []
        else:
            if reads:
                yield reads
                reads = []
            yield [step]
    if reads:
        yield reads

def build_synthesize_prompt(plan: ExecutionPlan, message: str) -> str:
    results = "\n\n".join(
        f"步骤 {step.step}（{step.action}）：\n{step.result[:6000]}"
        for step in plan.steps
    )
    return (
        f"用户请求：{message}\n目标：{plan.goal}\n各步骤结果：\n{results}\n\n"
        "根据结果给出最终回答，不重复过程，不编造失败步骤的结果。"
        "笔记搜索结果的编号、标题、(ID: ...) 必须保留。"
    )

async def run_plan_execute(
    question, user_id, session_factory, settings, *,
    history="", summary="", rag_context="", enable_thinking=False,
):
    from app.ai_service.react_agent import build_react_system_prompt
    from app.ai_service.reflection import stream_l1_refine, no_retry_tools

    wrote = False
    try:
        async with asyncio.timeout(settings.plan_total_timeout * (2 if enable_thinking else 1)):
            plan = await generate_plan(question, settings)
            if len(plan.steps) > settings.plan_execute_max_steps:
                raise ValueError("计划超过步骤上限")
            batches = topological_batches(plan.steps)
            yield {"type": "plan_start", "goal": plan.goal, "steps": [
                {"step": step.step, "action": step.action, "tool": step.tool}
                for step in plan.steps
            ]}
            previous = {}
            for batch in batches:
                for sub_batch in _safe_batches(batch, max(1, settings.plan_max_parallel_steps)):
                    failed = False
                    stream = _execute_batch(
                        sub_batch, question, previous, user_id, session_factory, settings,
                        history=history, summary=summary, rag_context=rag_context,
                        enable_thinking=enable_thinking,
                    )
                    try:
                        async for event in stream:
                            if event.get("type") == "tool_start":
                                spec = registry.get(event.get("name", ""))
                                wrote |= event.get("name") in no_retry_tools(settings) or spec is None or not spec.parallel_safe
                            failed |= event.get("type") == "error"
                            if event.get("type") != "error":
                                yield event
                    finally:
                        await stream.aclose()
                    if failed:
                        if wrote:
                            yield {"type": "error", "content": "部分操作可能已执行，请核对记录；不会自动重放写入"}
                        else:
                            yield {"type": "plan_fallback", "reason": "step_failed"}
                        return
                    previous.update({step.step: step.result for step in sub_batch})
            yield {"type": "plan_synthesize", "goal": plan.goal}
            system = build_react_system_prompt(question, rag_context=rag_context)
            history_text = json.dumps(history, ensure_ascii=False) if isinstance(history, list) else history
            prompt = (
                f"{system}\n历史摘要：{summary}\n近期对话：{history_text}\n\n"
                + build_synthesize_prompt(plan, question)
            )
            if settings.llm_api_key:
                answer = (await _complete(
                    prompt, settings, "plan_synthesize",
                    settings.plan_synthesize_timeout * (2 if enable_thinking else 1),
                    enable_thinking,
                )).strip()
            else:
                answer = "\n".join(step.result for step in plan.steps)
            if not answer:
                raise ValueError("综合结果为空")
            async for event in stream_l1_refine(
                question, answer, settings, plan_summary=plan.goal,
                step_results="\n".join(previous.values()), context=prompt,
                enable_thinking=enable_thinking,
            ):
                if event["type"] == "stream_done":
                    answer = event["full_response"]
                else:
                    yield event
            yield {"type": "response", "content": answer}
            yield {"type": "plan_complete", "goal": plan.goal}
            yield {"type": "stream_done", "full_response": answer}
    except Exception:
        logger.warning("Plan 执行失败", exc_info=True)
        if wrote:
            yield {"type": "error", "content": "部分操作已执行，结果汇总失败；请核对记录后再试"}
        else:
            yield {"type": "plan_fallback", "reason": "plan_failed"}

def thinking_text(self) -> str:
        if self.route == "plan_execute":
            return f"判定为复杂查询（{self.source}），走 Plan-Execute"
        if self.complexity == "complex":
            return (
                f"判定为复杂查询（{self.source}），Plan-Execute 不可用，本轮降级 ReAct"
            )
        return f"判定为简单查询（{self.source}），走 ReAct"

def set_classifier_fn(fn: ClassifierFn | None) -> None:
    global _injected
    _injected = fn

def decide_route(complexity: str, *, plan_available: bool = False) -> RouteName:
    if complexity == "complex":
        return "plan_execute" if plan_available else "plan_pending"
    return "react"

def _count_tool_keywords(message: str) -> int:
    matched: list[str] = []
    for keyword in sorted(TOOL_KEYWORDS, key=len, reverse=True):
        if keyword not in message:
            continue
        if any(keyword in existing for existing in matched):
            continue
        matched.append(keyword)
    return len(matched)

def rule_classify(
    message: str, settings: Settings, *, plan_available: bool = False
) -> ClassificationResult:
    """L1：能确定就返回 simple/complex；否则 reason=uncertain，调用方再决定是否上 L2。"""
    text = (message or "").strip()
    if not text:
        return ClassificationResult("simple", "rule", "empty", 1.0, "react")

    for pattern in _COMPLEX_RES:
        if pattern.search(text):
            return _final(
                "complex",
                "rule",
                f"匹配复杂模式: {pattern.pattern}",
                plan_available=plan_available,
            )

    question_marks = text.count("？") + text.count("?")
    min_length = settings.classifier_complex_min_length
    if len(text) > min_length and question_marks >= 2:
        return _final(
            "complex",
            "rule",
            f"长文本({len(text)}字符)+{question_marks}个问号",
            plan_available=plan_available,
        )

    matched_tools = _count_tool_keywords(text)
    if matched_tools >= 3:
        return _final(
            "complex",
            "rule",
            f"多目标并列: 匹配{matched_tools}个工具意图",
            plan_available=plan_available,
        )

    for pattern in _CONDITION_RES:
        if pattern.search(text):
            return _final(
                "complex",
                "rule",
                f"条件分支: 匹配 {pattern.pattern}",
                plan_available=plan_available,
            )

    for pattern in _SIMPLE_RES:
        if pattern.search(text):
            return _final(
                "simple",
                "rule",
                f"匹配简单模式: {pattern.pattern}",
                plan_available=plan_available,
            )

    has_tool_intent = any(keyword in text for keyword in TOOL_INTENT_KEYWORDS)
    if len(text) < settings.classifier_short_msg_length and not has_tool_intent:
        return _final(
            "simple",
            "rule",
            f"短消息({len(text)}字符)无工具意图",
            plan_available=plan_available,
        )

    if has_tool_intent and matched_tools == 1:
        return _final("simple", "rule", "单步工具操作", plan_available=plan_available)

    return ClassificationResult("simple", "rule", "uncertain", 0.0, "react")

def parse_classifier_payload(
    raw: str, *, plan_available: bool = False
) -> ClassificationResult:
    content = (raw or "").strip()
    content = re.sub(r"```json\s*", "", content)
    content = re.sub(r"```\s*", "", content).strip()
    try:
        data = json.loads(content)
    except json.JSONDecodeError:
        match = re.search(r"\{.*\}", content, re.DOTALL)
        if not match:
            return _final(
                "simple", "llm", "parse_error", 0.5, plan_available=plan_available
            )
        try:
            data = json.loads(match.group(0))
        except json.JSONDecodeError:
            return _final(
                "simple", "llm", "parse_error", 0.5, plan_available=plan_available
            )
    if not isinstance(data, dict):
        return _final(
            "simple", "llm", "parse_error", 0.5, plan_available=plan_available
        )
    complexity = data.get("complexity") or "simple"
    if complexity not in ("simple", "complex"):
        complexity = "simple"
    reason = str(data.get("reason") or "LLM 判定")[:40]
    return _final(complexity, "llm", reason, 0.8, plan_available=plan_available)

async def classify_query(
    message: str, settings: Settings, *, plan_available: bool = False
) -> ClassificationResult:
    text = (message or "").strip()
    if not settings.classifier_enabled:
        return _final(
            "simple", "fallback", "disabled", 1.0, plan_available=plan_available
        )
    if _injected is not None:
        result = await _injected(text)
        route = decide_route(result.complexity, plan_available=plan_available)
        return ClassificationResult(
            result.complexity,
            "inject",
            result.reason,
            result.confidence,
            route,
        )

    l1 = rule_classify(text, settings, plan_available=plan_available)
    if l1.reason != "uncertain":
        return l1

    if not settings.classifier_l2_enabled or not settings.llm_api_key:
        return _final(
            "simple", "fallback", "no_llm_default", 0.5, plan_available=plan_available
        )
    try:
        async with asyncio.timeout(settings.classifier_timeout):
            return await _llm_classify(text, settings, plan_available=plan_available)
    except Exception as exc:
        logger.warning("L2 分类失败，降级 simple: %s", exc)
        return _final(
            "simple", "fallback", "llm_fallback", 0.5, plan_available=plan_available
        )

def set_react_streamer(fn: ReactStreamer | None) -> None:
    global _injected
    _injected = fn

def build_react_system_prompt(
    message: str,
    *,
    rag_context: str = "",
    extra_system: str = "",
) -> str:
    parts = [DEFAULT_SYSTEM_PROMPT]
    extra = (extra_system or "").strip()
    if extra:
        parts.append(extra)
    context = (rag_context or "").strip()
    if context:
        parts.append(
            "以下是从知识库和笔记中检索到的相关内容，请在回答时优先参考：\n"
            f"<reference>\n{context}\n</reference>"
        )
    refs = referenced_notes_prompt(message)
    if refs:
        parts.append(f"用户本轮引用了笔记：\n{refs}")
    return "\n\n".join(parts)

def chunk_text(chunk: Any) -> str:
    content = getattr(chunk, "content", None)
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts: list[str] = []
        for item in content:
            if isinstance(item, str):
                parts.append(item)
            elif isinstance(item, dict) and item.get("type") == "text":
                parts.append(item.get("text") or "")
        return "".join(parts)
    return ""

def chunk_reasoning(chunk: Any) -> str:
    extra = getattr(chunk, "additional_kwargs", None) or {}
    if isinstance(extra, dict):
        text = extra.get("reasoning_content") or extra.get("reasoning") or ""
        if text:
            return str(text)
    return str(getattr(chunk, "reasoning_content", "") or "")

def map_langchain_event(
    event: dict[str, Any],
    *,
    consecutive_tool_calls: int,
    tool_start_times: dict[str, float],
    now: float | None = None,
) -> tuple[list[dict[str, Any]], int]:
    """把 astream_events v2 事件收成前端能用的 thinking / response / tool_*。"""
    event_type = event.get("event")
    produced: list[dict[str, Any]] = []
    stamp = time.time() if now is None else now

    if event_type == "on_chat_model_stream":
        chunk = (event.get("data") or {}).get("chunk")
        if chunk is None:
            return produced, consecutive_tool_calls
        reasoning = chunk_reasoning(chunk)
        if reasoning:
            produced.append(
                {"type": "thinking", "stage": "thinking", "content": reasoning}
            )
        text = chunk_text(chunk)
        if text:
            consecutive_tool_calls = 0
            produced.append({"type": "response", "content": text})
        return produced, consecutive_tool_calls

    if event_type == "on_tool_start":
        name = event.get("name") or "unknown"
        consecutive_tool_calls += 1
        tool_start_times[name] = stamp
        produced.append({"type": "tool_start", "name": name})
        if consecutive_tool_calls > MAX_CONSECUTIVE_TOOL_CALLS:
            produced.append(
                {
                    "type": "error",
                    "content": "抱歉，我在处理这个问题时遇到了困难（工具调用循环），请尝试换一种方式提问。",
                }
            )
            return produced, consecutive_tool_calls
        return produced, consecutive_tool_calls

    if event_type == "on_tool_end":
        name = event.get("name") or "unknown"
        started = tool_start_times.pop(name, None)
        duration_ms = 0 if started is None else round((stamp - started) * 1000)
        output = (event.get("data") or {}).get("output")
        result = getattr(output, "content", output)
        produced.append(
            {
                "type": "tool_end",
                "name": name,
                "duration_ms": duration_ms,
                "result": "" if result is None else str(result),
            }
        )
        return produced, consecutive_tool_calls

    if event_type == "on_tool_error":
        name = event.get("name") or "unknown"
        started = tool_start_times.pop(name, None)
        duration_ms = 0 if started is None else round((stamp - started) * 1000)
        err = (event.get("data") or {}).get("error")
        produced.append(
            {
                "type": "tool_end",
                "name": name,
                "duration_ms": duration_ms,
                "error": str(err or "工具执行失败"),
            }
        )
        return produced, consecutive_tool_calls

    return produced, consecutive_tool_calls

def _create_agent(model, tools, system_prompt: str):
    try:
        from langchain.agents import create_agent

        return create_agent(model=model, tools=tools or [], system_prompt=system_prompt)
    except ImportError:
        from langgraph.prebuilt import create_react_agent

        return create_react_agent(model, tools or [], prompt=system_prompt)

def _history_messages(history: str | list[dict], summary: str) -> list:
    from langchain_core.messages import AIMessage, HumanMessage, SystemMessage

    messages = []
    if (summary or "").strip():
        messages.append(SystemMessage(content=f"[历史对话摘要]\n{summary.strip()}"))
    if isinstance(history, list):
        for item in history:
            cls = HumanMessage if item["role"] == "user" else AIMessage
            messages.append(cls(content=item["content"]))
    elif (history or "").strip():
        messages.append(SystemMessage(content=f"近期对话：\n{history.strip()}"))
    return messages

async def run_langchain_react(
    question: str,
    user_id: str,
    session_factory,
    settings: Settings,
    *,
    history: str | list[dict] = "",
    summary: str = "",
    rag_context: str = "",
    enable_thinking: bool = False,
    timeout: int | None = None,
    tool_groups: list[str] | None = None,
    extra_system: str = "",
    reflect: bool = True,
    read_only: bool = False,
) -> AsyncIterator[dict[str, Any]]:
    from langchain_core.messages import HumanMessage

    from app.ai_service.thinking import agent_timeout
    timeout = agent_timeout(settings, enable_thinking, timeout=timeout)
    system_prompt = build_react_system_prompt(
        question, rag_context=rag_context, extra_system=extra_system
    )
    tools = build_langchain_tools(user_id, session_factory, tool_groups, read_only=read_only)
    model = _create_chat_model(
        settings, enable_thinking=enable_thinking, timeout=timeout
    )
    accumulated: list[str] = []
    try:
        import asyncio
        from app.ai_service.reflection import build_repair_note, no_retry_tools, stream_l1_refine

        async with asyncio.timeout(timeout):
            repair_note = ""
            for attempt in range(2):
                accumulated = []
                consecutive = 0
                tool_start_times: dict[str, float] = {}
                failure = None
                failed_tool = None
                touched_side_effect = False
                agent = _create_agent(model, tools, system_prompt)
                payload = {"messages": [
                    *_history_messages(history, summary),
                    HumanMessage(content=(visible_question(question) or question) + repair_note),
                ]}
                try:
                    async for event in agent.astream_events(
                        payload, version="v2", config={"recursion_limit": 30}
                    ):
                        mapped, consecutive = map_langchain_event(
                            event, consecutive_tool_calls=consecutive,
                            tool_start_times=tool_start_times,
                        )
                        for item in mapped:
                            kind = item.get("type")
                            if kind == "response":
                                accumulated.append(item.get("content") or "")
                            elif kind == "tool_start":
                                from app.ai_service.tool_registry import registry

                                spec = registry.get(item["name"])
                                touched_side_effect |= (
                                    item["name"] in no_retry_tools(settings)
                                    or spec is None or not spec.parallel_safe
                                )
                            elif kind == "tool_end" and item.get("error"):
                                failed_tool = item["name"]
                            elif kind == "error":
                                failure = item
                                break
                            yield item
                        if failure:
                            break
                except Exception as exc:
                    logger.warning("ReAct 执行失败", exc_info=True)
                    failure = {"type": "error", "content": "工具或模型执行失败，请稍后重试"}
                    repair_note = build_repair_note(failed_tool, type(exc).__name__)
                if failure is None:
                    break
                if attempt or not settings.reflection_l2_enabled or touched_side_effect:
                    yield failure
                    return
                yield {"type": "reflection", "stage": "repairing", "round": 1}
                yield {"type": "response_replace", "content": ""}
                repair_note = repair_note or build_repair_note(failed_tool, failure["content"])
            final = "".join(accumulated)
            if reflect:
                async for event in stream_l1_refine(
                    visible_question(question) or question, final, settings,
                    enable_thinking=enable_thinking, context=system_prompt,
                ):
                    if event["type"] == "stream_done":
                        refined = event["full_response"]
                        if refined != final:
                            yield {"type": "response_replace", "content": refined}
                        final = refined
                    else:
                        yield event
            yield {"type": "stream_done", "full_response": final}
    except TimeoutError:
        logger.warning("ReAct 响应超时 (timeout=%ss)", timeout)
        yield {"type": "error", "content": "生成超时，请稍后重试"}
    except Exception as exc:
        logger.warning("ReAct 执行失败: %s", exc)
        yield {"type": "error", "content": "生成失败，请稍后重试"}

def set_critique_fn(fn: CritiqueFn | None) -> None:
    global _injected
    _injected = fn

def parse_critique_response(raw: str) -> ReflectionVerdict:
    text = re.sub(r"```json\s*", "", raw or "")
    text = re.sub(r"```\s*", "", text).strip()
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        match = re.search(r"\{.*\}", text, re.DOTALL)
        if not match:
            logger.warning("批判 JSON 解析失败（视为通过）: %s", text[:200])
            return ReflectionVerdict(True)
        try:
            data = json.loads(match.group(0))
        except json.JSONDecodeError:
            logger.warning("批判 JSON 解析失败（视为通过）")
            return ReflectionVerdict(True)
    if not isinstance(data, dict):
        return ReflectionVerdict(True)
    passed = bool(data.get("pass", True))
    issues = str(data.get("issues") or "").strip()
    if not passed and not issues:
        logger.warning("批判判定不合格但 issues 为空（视为通过）")
        return ReflectionVerdict(True)
    return ReflectionVerdict(passed, issues)

def build_repair_note(failed_tool: str | None, error_content: str) -> str:
    tool_part = f"上次调用工具 `{failed_tool}` 失败" if failed_tool else "上次执行失败"
    return (
        f"\n\n[系统提示：{tool_part}（原因：{str(error_content)[:150]}）。"
        "请分析失败原因，修正参数或更换策略，最多再尝试 1 次工具调用；"
        "若无法确定修复方式，请直接基于已有信息回答，不要反复重试。]"
    )

def build_refine_prompt(user_message: str, draft: str, issues: str) -> str:
    return (
        f"你之前对用户问题「{(user_message or '')[:500]}」的回答未通过质量评审。

"
        f"上一版回答：
{(draft or '')[:4000]}

"
        f"评审意见（必须修正的问题）：
{issues}

"
        "请输出修正后的完整回答（只输出回答正文，不要解释修改过程）。"
    )

def no_retry_tools(settings: Settings) -> set[str]:
    raw = settings.reflection_no_retry_tools or "send_email"
    return {part.strip() for part in raw.split(",") if part.strip()}

async def critique_answer(
    user_message: str,
    draft: str,
    settings: Settings,
    *,
    plan_summary: str = "",
    step_results: str = "",
) -> ReflectionVerdict:
    if _injected is not None:
        return await _injected(user_message, draft, plan_summary)
    if not settings.llm_api_key:
        return ReflectionVerdict(True)
    from app.rag.llm import complete_openai_compatible
    from app.services import usage_service

    previous = (usage_service.get_trace_context() or {}).get("stage") or "chat"
    usage_service.set_trace_stage("reflection")
    try:
        from app.ai_service.thinking import complete_thinking_for

        from app.ai_service.models import settings_for_role

        role_settings = settings_for_role(settings, "reflection")
        raw = await complete_openai_compatible(
            build_critique_prompt(user_message, plan_summary, step_results, draft),
            role_settings,
            enable_thinking=complete_thinking_for("reflection", role_settings),
            timeout=settings.reflection_timeout,
        )
        return parse_critique_response(raw)
    except Exception as exc:
        logger.warning("批判调用异常（视为通过）: %s", exc)
        return ReflectionVerdict(True)
    finally:
        usage_service.set_trace_stage(previous)

async def stream_l1_refine(
    user_message: str, draft: str, settings: Settings, *,
    plan_summary: str = "", step_results: str = "",
    enable_thinking: bool = False, context: str = "",
):
    text = (draft or "").strip()
    enabled = (
        settings.reflection_l1_enabled
        and len(text) >= settings.reflection_min_answer_chars
        and (_injected is not None or settings.llm_api_key)
    )
    if enabled:
        yield {"type": "reflection", "stage": "checking", "round": 0}
        try:
            async with asyncio.timeout(settings.reflection_timeout):
                verdict = await critique_answer(
                    user_message, text, settings,
                    plan_summary=plan_summary, step_results=step_results,
                )
        except Exception:
            verdict = ReflectionVerdict(True)
        if not verdict.passed:
            yield {"type": "reflection", "stage": "refining", "round": 1}
            try:
                async with asyncio.timeout(settings.plan_synthesize_timeout * (2 if enable_thinking else 1)):
                    refined = await refine_answer(
                        user_message, text, verdict.issues, settings,
                        enable_thinking=enable_thinking, context=context,
                    )
                text = refined or text
            except Exception:
                logger.warning("L1 修正失败，保留草稿", exc_info=True)
        yield {"type": "reflection", "stage": "", "round": 0}
    yield {"type": "stream_done", "full_response": text}

