def set_agent_runner(fn: AgentRunner | None) -> None:
    global _injected
    _injected = fn

def match_local_tool(question: str) -> str | None:
    text = (question or "").strip()
    for name, keywords in TOOL_KEYWORDS:
        if any(key in text for key in keywords):
            return name
    return None

def should_use_agent(question: str, settings: Settings) -> bool:
    if not settings.agent_enabled:
        return False
    if _injected is not None:
        return True
    if match_local_tool(question):
        return True
    return False

async def run_local_tool(
    question: str,
    user_id: str,
    session_factory,
    settings: Settings,
    history: str = "",
) -> AsyncIterator[AgentEvent]:
    name = match_local_tool(question)
    if not name:
        return
    bound = registry.bind(bind_user_tools(user_id, session_factory))
    fn = bound.get(name)
    if fn is None:
        return
    yield {"type": "tool_start", "name": name}
    try:
        if name == "search_notes_tool":
            result = await fn(question)
        else:
            result = await fn()
    except Exception as exc:
        logger.warning("本地工具失败 %s: %s", name, exc)
        yield {"type": "tool_end", "name": name, "error": str(exc)}
        return
    yield {"type": "tool_end", "name": name, "result": result}
    yield {"type": "response", "content": result}

def sse_notice(self) -> dict[str, str] | None:
        if self.reason == "attachment" and self.requested:
            return {
                "type": "thinking",
                "stage": "attachment",
                "content": ATTACHMENT_THINKING_NOTICE,
            }
        if self.reason == "unsupported" and self.requested:
            return {
                "type": "thinking",
                "stage": "unsupported",
                "content": UNSUPPORTED_THINKING_NOTICE,
            }
        return None

def thinking_protocol(settings: Settings) -> ThinkingProtocol:
    """auto：百炼域名才走 enable_thinking；其余接口默认不传这个字段。"""
    mode = (settings.llm_thinking_protocol or "auto").strip().lower()
    if mode in {"none", "off", "openai"}:
        return "none"
    if mode == "dashscope":
        return "dashscope"
    url = (settings.llm_base_url or "").lower()
    if "dashscope.aliyuncs.com" in url:
        return "dashscope"
    return "none"

def extra_body(enable_thinking: bool, settings: Settings) -> dict[str, bool] | None:
    """ChatOpenAI extra_body。非百炼返回 None，调用方不要把空字典传上去。"""
    if thinking_protocol(settings) != "dashscope":
        return None
    return {"enable_thinking": bool(enable_thinking)}

def payload_thinking_fields(enable_thinking: bool, settings: Settings) -> dict[str, bool]:
    """补全请求体。非百炼返回空 dict，避免带上非法参数。"""
    body = extra_body(enable_thinking, settings)
    return dict(body) if body is not None else {}

def resolve_agent_thinking(
    requested: bool,
    *,
    has_attachments: bool = False,
    settings: Settings | None = None,
) -> ThinkingDecision:
    if has_attachments:
        return ThinkingDecision(bool(requested), False, "attachment")
    if not requested:
        return ThinkingDecision(False, False, "off")
    if settings is not None and thinking_protocol(settings) != "dashscope":
        return ThinkingDecision(True, False, "unsupported")
    return ThinkingDecision(True, True, "agent")

def complete_thinking_for(role: CompleteRole, settings: Settings) -> bool:
    if thinking_protocol(settings) != "dashscope":
        return False
    if role == "classifier":
        return bool(settings.classifier_enable_thinking)
    if role == "plan":
        return bool(settings.plan_enable_thinking)
    if role == "reflection":
        return bool(settings.reflection_enable_thinking)
    return False

def agent_timeout(
    settings: Settings, enable_thinking: bool, *, timeout: int | None = None
) -> int:
    base = timeout or settings.llm_stream_timeout
    return base * 2 if enable_thinking else base

def __init__(self) -> None:
        self._groups: dict[str, list[str]] = {}
        self._specs: dict[str, ToolSpec] = {}

def register(self, spec: ToolSpec) -> None:
        if spec.name in self._specs:
            raise ValueError(f"工具名冲突: {spec.name}")
        self._specs[spec.name] = spec
        self._groups.setdefault(spec.group, []).append(spec.name)

def resolve(self, groups: list[str] | None = None) -> list[ToolSpec]:
        if groups is None:
            names = [name for names in self._groups.values() for name in names]
        else:
            names = []
            seen: set[str] = set()
            for group in groups:
                for name in self._groups.get(group, []):
                    if name not in seen:
                        seen.add(name)
                        names.append(name)
        return [self._specs[name] for name in names if name in self._specs]

def unregister(self, name: str) -> None:
        self._specs.pop(name, None)
        for names in self._groups.values():
            while name in names:
                names.remove(name)

def bind(self, builtins: dict[str, Callable]) -> dict[str, Callable]:
        return {
            spec.name: spec.fn or builtins[spec.name]
            for spec in self.resolve()
            if spec.fn is not None or spec.name in builtins
        }

def groups_for(self, name: str) -> list[str] | None:
        spec = self.get(name)
        if spec is None:
            return None
        groups = ["base", spec.group]
        if spec.group == "note_write":
            groups.append("note_read")
        return list(dict.fromkeys(groups))

def _clip(text: str, limit: int) -> str:
    text = text or ""
    if len(text) <= limit:
        return text
    return text[:limit] + "…"

async def _resolve_category_id(
    db: AsyncSession, user_id: str, name: str | None
) -> str | None:
    if not name or not name.strip():
        return None
    cat = (
        await db.execute(
            select(NoteCategory).where(
                NoteCategory.user_id == user_id,
                NoteCategory.name == name.strip(),
                NoteCategory.deleted_at.is_(None),
            )
        )
    ).scalar_one_or_none()
    return cat.id if cat else None

def bind_user_tools(user_id: str, session_factory) -> dict[str, Callable[..., Any]]:
    """把工具闭包绑到当前用户。返回 name → async callable。"""

    async def what_time_is_now() -> str:
        return datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    async def get_user_info_tools() -> str:
        async with session_factory() as db:
            user = (
                await db.execute(select(User).where(User.uuid == user_id))
            ).scalar_one_or_none()
        if user is None:
            return f"当前用户 ID: {user_id}（用户信息获取失败）"
        email = user.email or "未设置邮箱"
        return f"用户名: {user.username}\n邮箱: {email}\n用户ID: {user_id}"

    async def search_notes_tool(query: str, top_k: int = 5) -> str:
        top_k = max(1, min(int(top_k or 5), 10))
        cards: list[dict] = []
        try:
            from app.rag.vector_store import get_vector_store

            hits = await get_vector_store().search(query, user_id, top_k * 3, collection="notes")
        except Exception:
            logger.warning("笔记向量搜索失败，回退关键词", exc_info=True)
            hits = []
        async with session_factory() as db:
            seen = set()
            for item in hits:
                note_id = item.get("note_id")
                if not note_id or note_id in seen:
                    continue
                try:
                    note = await note_service.get_active_note(db, user_id, note_id)
                except BusinessError:
                    continue
                seen.add(note_id)
                cards.append({"title": note.title, "note_id": note.id, "excerpt": note.content or ""})
                if len(cards) >= top_k:
                    break
            if cards:
                return format_note_search_cards(query, cards)
            data = await note_service.keyword_search(db, user_id, query, top_k)
            hits = data.get("results") or []
            for item in hits:
                summary = item.get("note") or {}
                note_id = summary.get("id")
                if not note_id:
                    continue
                try:
                    note = await note_service.get_active_note(db, user_id, note_id)
                except BusinessError:
                    continue
                cards.append(
                    {
                        "title": note.title,
                        "note_id": note.id,
                        "excerpt": note.content or "",
                    }
                )
        return format_note_search_cards(query, cards)

    async def get_note_content_tool(note_id: str) -> str:
        async with session_factory() as db:
            try:
                note = await note_service.get_active_note(db, user_id, note_id)
            except BusinessError:
                return "未找到笔记或无权访问"
        tags = ",".join(note.tags or []) or "无"
        updated = note.updated_at.strftime("%Y-%m-%d") if note.updated_at else "未知"
        body = _clip(note.content or "", MAX_NOTE_CHARS)
        return (
            f"# {note.title}\n\n> 标签：{tags} | 更新日期：{updated}\n\n---\n\n{body}"
        )

    async def get_note_stats_tool() -> str:
        async with session_factory() as db:
            category_name = func.coalesce(NoteCategory.name, "未分类").label(
                "category_name"
            )
            rows = list(
                (
                    await db.execute(
                        select(category_name, func.count().label("note_count"))
                        .select_from(Note)
                        .outerjoin(
                            NoteCategory,
                            and_(
                                Note.category_id == NoteCategory.id,
                                NoteCategory.deleted_at.is_(None),
                            ),
                        )
                        .where(
                            Note.user_id == user_id,
                            Note.deleted_at.is_(None),
                            (Note.category_id.is_(None))
                            | (NoteCategory.id.is_not(None)),
                        )
                        .group_by(NoteCategory.id, NoteCategory.name)
                    )
                ).all()
            )
        if not rows:
            return "暂无笔记"
        ordered = sorted(rows, key=lambda r: r[0] == "未分类")
        lines = [f"- {name}: {count} 篇" for name, count in ordered]
        return "笔记分类统计:\n" + "\n".join(lines)

    async def today_reviews() -> str:
        async with session_factory() as db:
            return await get_today_reviews_tool(db, user_id)

    async def mark_reviewed(review_id: int) -> str:
        async with session_factory() as db:
            try:
                text = await mark_reviewed_tool(db, user_id, int(review_id))
                await db.commit()
                return text
            except BusinessError:
                await db.rollback()
                return "未找到回顾记录或无权操作"
            except Exception as exc:
                await db.rollback()
                logger.warning("标记回顾失败: %s", exc)
                return "标记回顾失败，请稍后重试"

    async def create_note_tool(
        title: str, content: str, tags: str = "", category: str = ""
    ) -> str:
        tag_list = [part.strip() for part in (tags or "").split(",") if part.strip()]
        async with session_factory() as db:
            category_id = await _resolve_category_id(db, user_id, category)
            note = await note_service.create_note(
                db,
                user_id,
                NoteCreate(
                    title=title, content=content, tags=tag_list, category_id=category_id
                ),
            )
            await db.commit()
            return f"笔记创建成功！ID: {note.id}, 标题: {note.title}"

    async def update_note_tool(
        note_id: str,
        title: str | None = None,
        content: str | None = None,
        tags: str | None = None,
        category: str | None = None,
    ) -> str:
        fields: dict[str, Any] = {}
        if title is not None:
            fields["title"] = title
        if content is not None:
            fields["content"] = content
        if tags is not None:
            fields["tags"] = [part.strip() for part in tags.split(",") if part.strip()]
        async with session_factory() as db:
            if category is not None:
                fields["category_id"] = await _resolve_category_id(
                    db, user_id, category
                )
            if not fields:
                return "未提供任何要更新的字段"
            try:
                note = await note_service.update_note(db, user_id, note_id, fields)
                await db.commit()
                return f"笔记更新成功！ID: {note.id}, 标题: {note.title}"
            except BusinessError:
                await db.rollback()
                return "未找到笔记或无权访问"
            except Exception as exc:
                await db.rollback()
                logger.warning("笔记更新失败: %s", exc)
                return "笔记更新失败，请稍后重试"

    async def get_related_notes_tool(note_title: str, top_k: int = 3) -> str:
        return await search_notes_tool(note_title, top_k)

    return {
        "what_time_is_now": what_time_is_now,
        "get_user_info_tools": get_user_info_tools,
        "search_notes_tool": search_notes_tool,
        "get_note_content_tool": get_note_content_tool,
        "get_note_stats_tool": get_note_stats_tool,
        "get_today_reviews_tool": today_reviews,
        "mark_reviewed_tool": mark_reviewed,
        "create_note_tool": create_note_tool,
        "update_note_tool": update_note_tool,
        "get_related_notes_tool": get_related_notes_tool,
    }

async def search_notes_tool(query: str, top_k: int = 5) -> str:
        top_k = max(1, min(int(top_k or 5), 10))
        cards: list[dict] = []
        try:
            from app.rag.vector_store import get_vector_store

            hits = await get_vector_store().search(query, user_id, top_k * 3, collection="notes")
        except Exception:
            logger.warning("笔记向量搜索失败，回退关键词", exc_info=True)
            hits = []
        async with session_factory() as db:
            seen = set()
            for item in hits:
                note_id = item.get("note_id")
                if not note_id or note_id in seen:
                    continue
                try:
                    note = await note_service.get_active_note(db, user_id, note_id)
                except BusinessError:
                    continue
                seen.add(note_id)
                cards.append({"title": note.title, "note_id": note.id, "excerpt": note.content or ""})
                if len(cards) >= top_k:
                    break
            if cards:
                return format_note_search_cards(query, cards)
            data = await note_service.keyword_search(db, user_id, query, top_k)
            hits = data.get("results") or []
            for item in hits:
                summary = item.get("note") or {}
                note_id = summary.get("id")
                if not note_id:
                    continue
                try:
                    note = await note_service.get_active_note(db, user_id, note_id)
                except BusinessError:
                    continue
                cards.append(
                    {
                        "title": note.title,
                        "note_id": note.id,
                        "excerpt": note.content or "",
                    }
                )
        return format_note_search_cards(query, cards)

