async def check_and_summarize(
    db: AsyncSession, session_id: str, settings: Settings
) -> ChatSummary | None:
    """消息足够多时压缩窗口外旧对话。失败返回已有摘要，不抛给主流程。"""
    try:
        if not settings.memory_summarize_enabled:
            return await get_summary(db, session_id)

        msg_count = (
            await db.execute(
                select(func.count(ChatMessage.id)).where(
                    ChatMessage.session_id == session_id
                )
            )
        ).scalar() or 0
        if msg_count < settings.memory_summarize_threshold:
            return await get_summary(db, session_id)

        existing = await get_summary(db, session_id)
        existing_text = existing.summary_text if existing else ""
        last_id = existing.last_message_id if existing else 0

        new_count = (
            await db.execute(
                select(func.count(ChatMessage.id)).where(
                    ChatMessage.session_id == session_id,
                    ChatMessage.id > last_id,
                )
            )
        ).scalar() or 0
        if new_count < settings.memory_min_summary_interval:
            return existing

        compress_messages = list(
            (
                await db.execute(
                    select(ChatMessage)
                    .where(
                        ChatMessage.session_id == session_id,
                        ChatMessage.id > last_id,
                    )
                    .order_by(ChatMessage.id.asc())
                )
            )
            .scalars()
            .all()
        )
        keep_recent = max(settings.memory_keep_recent, 0)
        if len(compress_messages) <= keep_recent:
            return existing
        to_compress = (
            compress_messages[:-keep_recent] if keep_recent else compress_messages
        )

        prompt = build_summary_prompt(existing_text, to_compress)
        new_summary = await _complete_summary(prompt, settings)
        if not new_summary:
            return existing
        new_summary = truncate_summary(new_summary, settings.memory_summary_max_tokens)
        if not new_summary:
            return existing
        return await update_summary(db, session_id, new_summary, to_compress[-1].id)
    except Exception as exc:
        logger.warning("摘要检查/生成失败（不影响主流程）: %s", exc)
        try:
            return await get_summary(db, session_id)
        except Exception:
            return None

def one_line(text: str, max_chars: int = 30) -> str:
    collapsed = " ".join((text or "").split())
    if len(collapsed) <= max_chars:
        return collapsed
    return collapsed[:max_chars].rstrip() + "…"

def format_note_search_cards(query: str, items: list[dict]) -> str:
    """items: title / note_id / excerpt。空列表返回固定未找到文案。"""
    if not items:
        return "未找到相关笔记"
    keyword = (query or "").strip() or "关键词"
    lines = [f'找到 {len(items)} 篇与"{keyword}"相关的笔记：']
    for index, item in enumerate(items, start=1):
        title = (item.get("title") or "未命名").strip() or "未命名"
        note_id = (item.get("note_id") or "").strip()
        excerpt = one_line(item.get("excerpt") or "", 30)
        head = f"{index}. {title}"
        if note_id:
            head += f" (ID: {note_id})"
        if excerpt:
            head += f" - {excerpt}"
        lines.append(head)
    return "\n".join(lines)

def visible_question(message: str) -> str:
    """去掉引用卡片后的用户原问题，给标题和检索用。"""
    text = message or ""
    marker = text.find(CONTEXT_MARKER)
    if marker < 0:
        return text.strip()
    prefix = text[:marker]
    prefix = re.sub(r"\s*[-—–]+\s*$", "", prefix).strip()
    return prefix or text.strip()

def referenced_notes_prompt(message: str) -> str:
    """有引用块时抽出给 Agent 的上下文；没有则空串。"""
    text = message or ""
    if CONTEXT_MARKER not in text and not REF_BLOCK_RE.search(text):
        return ""
    return text.strip()

def set_route_fn(fn: RouteFn | None) -> None:
    global _injected
    _injected = fn

async def decide_retrieval(question: str, user_id: str, settings: Settings) -> RouteDecision:
    """返回是否检索。关闭开关时始终检索；算分失败时也检索。"""
    query = (question or "").strip()
    if not query:
        return RouteDecision(False, float("inf"), "empty")
    if not settings.rag_route_enabled:
        return RouteDecision(True, 0.0, "disabled")

    if _injected is not None:
        return await _injected(query, user_id, settings)

    try:
        from app.rag.vector_store import get_vector_store

        distance = await get_vector_store().compute_route_score(query, user_id)
    except Exception as exc:
        logger.warning("RAG 路由打分失败，继续检索: %s", exc)
        return RouteDecision(True, float("inf"), "score_failed")

    if distance > settings.rag_route_threshold:
        logger.debug(
            "跳过检索: distance=%.3f > threshold=%.3f",
            distance,
            settings.rag_route_threshold,
        )
        return RouteDecision(False, distance, "above_threshold")
    return RouteDecision(True, distance, "below_threshold")

def set_summarize_fn(fn: SummarizeFn | None) -> None:
    global _injected
    _injected = fn

def truncate_text(text: str, max_chars: int) -> str:
    raw = text or ""
    if max_chars <= 0 or len(raw) <= max_chars:
        return raw
    return raw[:max_chars]

async def _complete_summary(query: str, document: str, settings: Settings) -> str:
    from app.services.usage_service import UsageTimer, set_trace_stage

    set_trace_stage("rag_summary")
    if _injected is not None:
        timer = UsageTimer("rag_summary", settings.llm_model)
        try:
            text = (await _injected(query, document)).strip()
            await timer.finish(query, text)
            return text
        except Exception as exc:
            await timer.finish(query, "", success=False, error=str(exc))
            raise
    if not settings.llm_api_key:
        return ""
    from app.rag.llm import complete_openai_compatible

    prompt = build_summarize_prompt(
        query, truncate_text(document, settings.rag_summarize_input_max_chars)
    )
    return (await complete_openai_compatible(prompt, settings)).strip()

async def _summarize_one(query: str, hit: dict, settings: Settings) -> dict:
    content = (hit.get("content") or "").strip()
    max_chars = settings.rag_summarize_truncate_max_chars
    if not content:
        return _copy_hit(hit, "")
    if not settings.rag_summarize_enabled:
        return _copy_hit(hit, truncate_text(content, max_chars))

    try:
        text = await _complete_summary(query, content, settings)
        if not text:
            return _copy_hit(hit, truncate_text(content, max_chars))
        return _copy_hit(hit, text)
    except Exception as exc:
        logger.warning("检索后摘要失败，回退截断: %s", exc)
        return _copy_hit(hit, truncate_text(content, max_chars))

async def summarize_hits(
    query: str, hits: list[dict], settings: Settings
) -> list[dict]:
    """返回用于拼提示 / 算 Token 的命中副本。原 hits 不改，留给 API sources。"""
    if not hits:
        return []
    results = await asyncio.gather(
        *[_summarize_one(query, hit, settings) for hit in hits]
    )
    return list(results)

def set_rerank_fn(fn: RerankFn | None) -> None:
    global _injected_rerank
    _injected_rerank = fn

def _as_float_list(scores: Any, expected: int) -> list[float]:
    if hasattr(scores, "tolist"):
        scores = scores.tolist()
    if isinstance(scores, (int, float)):
        if expected == 1:
            return [float(scores)]
        raise ValueError("重排序只返回了一个分数")
    values = [float(item) for item in scores]
    if len(values) != expected:
        raise ValueError(f"重排序条数不匹配 ({len(values)} != {expected})")
    return values

def cross_encoder_scores(query: str, documents: list[str], model: Any) -> list[float]:
    """sentence-transformers.CrossEncoder 用 predict；FlagEmbedding 用 compute_score。"""
    pairs = [(query, doc) for doc in documents]
    if hasattr(model, "predict"):
        scores = model.predict(pairs)
    elif hasattr(model, "compute_score"):
        scores = model.compute_score(pairs)
    else:
        raise AttributeError("重排序模型既没有 predict 也没有 compute_score")
    return _as_float_list(scores, len(documents))

def _cached_rerank_dir(model_name: str) -> str | None:
    """Hugging Face 缓存里已有该模型时返回本地目录，避免再 HEAD Hub。"""
    if not model_name:
        return None
    if os.path.isdir(model_name):
        return model_name
    try:
        from huggingface_hub import try_to_load_from_cache
        from huggingface_hub.file_download import _CACHED_NO_EXIST

        cached = try_to_load_from_cache(repo_id=model_name, filename="config.json")
        if cached is None or cached is _CACHED_NO_EXIST:
            return None
        return os.path.dirname(str(cached))
    except Exception:
        return None

def _apply_hub_offline_env(enabled: bool) -> dict[str, str | None]:
    keys = ("HF_HUB_OFFLINE", "TRANSFORMERS_OFFLINE")
    previous = {key: os.environ.get(key) for key in keys}
    if enabled:
        for key in keys:
            os.environ[key] = "1"
    return previous

def _restore_hub_offline_env(previous: dict[str, str | None]) -> None:
    for key, value in previous.items():
        if value is None:
            os.environ.pop(key, None)
        else:
            os.environ[key] = value

def _load_cross_encoder(model_name: str, *, local_files_only: bool) -> Any:
    """加载 CrossEncoder。

    bge-reranker 不是 sentence-transformers 仓库，没有 modules.json。
    传 Hub id 且允许联网时，ST 每次都会 HEAD huggingface.co/.../modules.json。
    有本地缓存时必须传本地目录 + local_files_only，并临时打开 HF 离线环境变量。
    """
    from sentence_transformers import CrossEncoder

    kwargs: dict[str, Any] = {}
    try:
        params = inspect.signature(CrossEncoder.__init__).parameters
    except (TypeError, ValueError):
        params = {}
    if "local_files_only" in params:
        kwargs["local_files_only"] = local_files_only
    if "model_kwargs" in params:
        kwargs["model_kwargs"] = {"local_files_only": local_files_only}
    elif "automodel_args" in params:
        kwargs["automodel_args"] = {"local_files_only": local_files_only}
    if "tokenizer_kwargs" in params:
        kwargs["tokenizer_kwargs"] = {"local_files_only": local_files_only}
    if "processor_kwargs" in params:
        kwargs["processor_kwargs"] = {"local_files_only": local_files_only}
    if "config_kwargs" in params:
        kwargs["config_kwargs"] = {"local_files_only": local_files_only}

    previous = _apply_hub_offline_env(local_files_only)
    try:
        return CrossEncoder(model_name, **kwargs)
    finally:
        _restore_hub_offline_env(previous)

def get_or_load_cross_encoder(settings: Settings | None) -> Any | None:
    """已注入则直接用；否则按配置懒加载。失败记一次，之后不再试。"""
    global _cross_encoder, _cross_encoder_failed
    if _cross_encoder is not None:
        return _cross_encoder
    if _cross_encoder_failed or settings is None or not settings.rerank_enabled:
        return None
    if settings.app_env == "test" and not settings.rerank_download:
        return None

    with _cross_encoder_lock:
        if _cross_encoder is not None:
            return _cross_encoder
        if _cross_encoder_failed:
            return None
        try:
            cached_dir = _cached_rerank_dir(settings.rerank_model)
            source = cached_dir or settings.rerank_model
            local_only = cached_dir is not None or not settings.rerank_download
            _cross_encoder = _load_cross_encoder(source, local_files_only=local_only)
            logger.info("重排序模型已加载: %s", source)
            return _cross_encoder
        except Exception as exc:
            _cross_encoder_failed = True
            logger.warning("重排序模型加载失败，回退词重叠: %s", exc)
            return None

def tokenize(text: str) -> list[str]:
    """英文按词；连续汉字拆成单字 + 双字，便于 BM25 打到词组。"""
    tokens: list[str] = []
    for raw in TOKEN_RE.findall((text or "").lower()):
        if _CJK_RE.search(raw) and len(raw) > 1:
            chars = list(raw)
            tokens.extend(chars)
            tokens.extend(raw[i : i + 2] for i in range(len(raw) - 1))
        else:
            tokens.append(raw)
    return tokens

def rrf_fuse(
    ranked_lists: Sequence[Sequence[dict]],
    *,
    k: int = 60,
    id_field: str = "chunk_id",
) -> list[dict]:
    """倒数排名融合。同一文档出现在多路里会累加 1/(k+rank)。"""
    k = max(k, 1)
    merged: dict[str, dict] = {}
    rrf: dict[str, float] = {}
    for hits in ranked_lists:
        for rank, hit in enumerate(hits, start=1):
            chunk_id = str(hit.get(id_field) or "")
            if not chunk_id:
                continue
            rrf[chunk_id] = rrf.get(chunk_id, 0.0) + 1.0 / (k + rank)
            if chunk_id not in merged:
                merged[chunk_id] = dict(hit)
    ordered = sorted(
        merged.values(),
        key=lambda item: rrf.get(str(item.get(id_field)), 0.0),
        reverse=True,
    )
    for item in ordered:
        item["rrf_score"] = rrf.get(str(item.get(id_field)), 0.0)
        item["score"] = item["rrf_score"]
    return ordered

def overlap_scores(query: str, documents: list[str]) -> list[float]:
    """查询词覆盖率：命中的查询 token 数 / 查询 token 数。"""
    query_set = set(tokenize(query))
    if not query_set:
        return [0.0] * len(documents)
    scores: list[float] = []
    for text in documents:
        tokens = set(tokenize(text))
        scores.append(len(query_set & tokens) / len(query_set))
    return scores

def _score_hits(
    query: str, documents: list[str], settings: Settings | None
) -> list[float]:
    if _injected_rerank is not None:
        return _injected_rerank(query, documents)
    model = get_or_load_cross_encoder(settings)
    if model is not None:
        return cross_encoder_scores(query, documents, model)
    return overlap_scores(query, documents)

def rerank_hits(
    query: str,
    hits: list[dict],
    *,
    top_n: int | None = None,
    settings: Settings | None = None,
) -> list[dict]:
    """注入函数 > CrossEncoder > 词重叠。失败则保持融合顺序。"""
    if not hits:
        return []
    documents = [str(hit.get("content") or "") for hit in hits]
    try:
        scores = _score_hits(query, documents, settings)
        if len(scores) != len(hits):
            raise ValueError(f"重排序条数不匹配 ({len(scores)} != {len(hits)})")
    except Exception as exc:
        logger.warning("重排序失败，使用融合顺序: %s", exc)
        return hits[:top_n] if top_n is not None else hits
    for hit, score in zip(hits, scores):
        hit["rerank_score"] = float(score)
        hit["score"] = float(score)
    ranked = sorted(
        hits, key=lambda item: item.get("rerank_score") or 0.0, reverse=True
    )
    if top_n is not None:
        return ranked[:top_n]
    return ranked

def set_title_fn(fn: TitleFn | None) -> None:
    global _injected
    _injected = fn

def fallback_title(question: str, max_chars: int = 40) -> str:
    text = " ".join((question or "").strip().split())
    if not text:
        return DEFAULT_TITLE
    return text[: max(1, max_chars)]

def sanitize_title(raw: str, *, max_chars: int, fallback: str) -> str:
    text = " ".join((raw or "").strip().split())
    text = _QUOTE_RE.sub("", text).strip()
    if not text:
        return fallback
    return text[:max_chars]

def __init__(self, chunk_size: int = 400, chunk_overlap: int = 80):
        if chunk_size < 50:
            raise ValueError("chunk_size 过小")
        if chunk_overlap >= chunk_size:
            raise ValueError("chunk_overlap 必须小于 chunk_size")
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap

def split(self, text: str, doc_type: str = "txt") -> list[TextChunk]:
        cleaned = (text or "").strip()
        if not cleaned:
            return []

        kind = doc_type.lower().replace("text/", "")
        if kind in {"md", "markdown"}:
            raw = self._split_markdown(cleaned)
        else:
            raw = [TextChunk(content=c) for c in self._split_generic(cleaned)]

        chunks = [c for c in raw if c.content.strip()]
        for i, chunk in enumerate(chunks):
            chunk.chunk_index = i
        return chunks

def _split_markdown(self, text: str) -> list[TextChunk]:
        sections = self._parse_sections(text)
        if not sections:
            return [TextChunk(content=c) for c in self._split_generic(text)]

        result: list[TextChunk] = []
        for section in sections:
            body = text[section["start"] : section["end"]].strip()
            if not body:
                continue
            for piece in self._split_generic(body):
                result.append(TextChunk(content=piece, section_title=section["title"]))
        return result

def _parse_sections(self, text: str) -> list[dict]:
        headings = [
            (m.start(), len(m.group(1)), m.group(2).strip())
            for m in _HEADING_RE.finditer(text)
        ]
        if not headings:
            return []

        sections: list[dict] = []
        if headings[0][0] > 0 and text[: headings[0][0]].strip():
            sections.append({"start": 0, "end": headings[0][0], "title": ""})

        for i, (pos, level, title) in enumerate(headings):
            end = headings[i + 1][0] if i + 1 < len(headings) else len(text)
            sections.append({
                "start": pos,
                "end": end,
                "title": f"{'#' * level} {title}",
            })
        return sections

def _split_generic(self, text: str) -> list[str]:
        paragraphs = [p.strip() for p in re.split(r"\n\s*\n", text) if p.strip()]
        if not paragraphs:
            return self._window(text)

        pieces: list[str] = []
        buf = ""
        for para in paragraphs:
            if len(para) > self.chunk_size:
                if buf:
                    pieces.append(buf)
                    buf = ""
                pieces.extend(self._window(para))
                continue
            candidate = f"{buf}\n\n{para}".strip() if buf else para
            if len(candidate) <= self.chunk_size:
                buf = candidate
            else:
                pieces.append(buf)
                buf = para
        if buf:
            pieces.append(buf)
        return pieces

def _window(self, text: str) -> list[str]:
        if len(text) <= self.chunk_size:
            return [text] if text.strip() else []
        step = self.chunk_size - self.chunk_overlap
        chunks: list[str] = []
        start = 0
        while start < len(text):
            end = min(start + self.chunk_size, len(text))
            piece = text[start:end].strip()
            if piece:
                chunks.append(piece)
            if end >= len(text):
                break
            start += step
        return chunks

def get_encoder(cls, model_name: str = "cl100k_base"):
        if model_name not in cls._encoders:
            try:
                import tiktoken

                cls._encoders[model_name] = tiktoken.get_encoding(model_name)
            except Exception as exc:
                logger.warning("tiktoken 加载失败，回退到字符估算: %s", exc)
                cls._encoders[model_name] = None
        return cls._encoders[model_name]

def count(cls, text: str, model_name: str = "cl100k_base") -> int:
        if not text:
            return 0
        encoder = cls.get_encoder(model_name)
        if encoder:
            return len(encoder.encode(text))
        return max(1, len(text) // 2)

def _ensure(self):
        if self._rag is not None and self._notes is not None:
            return
        if self._client is None:
            import chromadb
            from chromadb.config import Settings as ChromaSettings

            self._client = chromadb.PersistentClient(
                path=self.settings.chroma_persist_dir,
                settings=ChromaSettings(anonymized_telemetry=False),
            )
        self._rag = self._client.get_or_create_collection(
            name=self.settings.chroma_collection_rag,
            metadata={"hnsw:space": "cosine"},
        )
        self._notes = self._client.get_or_create_collection(
            name=self.settings.chroma_collection_notes,
            metadata={"hnsw:space": "cosine"},
        )

def _collection(self, name: CollectionName):
        self._ensure()
        return self._rag if name == "rag" else self._notes

async def _check_dimension(self, probe: list[float]) -> None:
        """集合非空时，已存向量维度必须和当前模型输出一致。"""
        if self._dim_checked:
            return
        model_dim = len(probe)
        for name, col in (("rag", self._rag), ("notes", self._notes)):
            if col is None or col.count() == 0:
                continue
            stored = (col.get(limit=1, include=["embeddings"]) or {}).get("embeddings")
            if stored is None or len(stored) == 0:
                continue
            first = stored[0]
            stored_dim = first.shape[0] if hasattr(first, "shape") else len(first)
            if stored_dim != model_dim:
                raise BusinessError(
                    code=ErrorCode.EMBEDDING_DIM_MISMATCH,
                    http_status=500,
                    detail=(
                        f"集合 {name} 为 {stored_dim} 维，当前模型输出 {model_dim} 维。"
                        "请删除 data/chroma 后重新上传文档并保存笔记。"
                    ),
                )
        self._dim_checked = True

def _candidate_k(self, top_k: int) -> int:
        multiplier = max(self.settings.hybrid_candidate_multiplier, 1)
        cap = max(self.settings.hybrid_max_candidates, top_k)
        return min(max(top_k * multiplier, top_k), cap)

def _maybe_rerank(
        self, query: str, hits: list[dict], top_k: int, enabled: bool
    ) -> list[dict]:
        if not hits:
            return []
        if enabled and self.settings.rerank_enabled:
            return rerank_hits(query, hits, top_n=top_k, settings=self.settings)
        return hits[:top_k]

