def parse_tags(raw: str) -> list[str]:
    parts = re.split(r"[,，、\n]+", raw or "")
    tags: list[str] = []
    seen: set[str] = set()
    for part in parts:
        tag = part.strip().lstrip("#").strip()
        if not tag or tag.lower() in seen:
            continue
        seen.add(tag.lower())
        tags.append(tag[:20])
        if len(tags) >= 5:
            break
    return tags

