def parse_usage(data: dict | None, prompt: str, completion: str) -> tuple[int, int, int]:
    usage = (data or {}).get("usage") or {}
    prompt_tokens = int(usage["prompt_tokens"]) if usage.get("prompt_tokens") is not None else estimate_tokens(prompt)
    completion_tokens = int(usage["completion_tokens"]) if usage.get("completion_tokens") is not None else estimate_tokens(completion)
    total = int(usage["total_tokens"]) if usage.get("total_tokens") is not None else prompt_tokens + completion_tokens
    return prompt_tokens, completion_tokens, total

async def seed_model_pricing(db: AsyncSession, settings: Settings | None = None) -> None:
    settings = settings or get_settings()
    pricing: dict[str, dict[str, Any]] = dict(DEFAULT_PRICING)
    if settings.llm_model and settings.llm_model not in pricing:
        pricing[settings.llm_model] = {
            "input_price_per_1k": 0.0008,
            "output_price_per_1k": 0.002,
            "currency": "CNY",
        }
    for model, values in pricing.items():
        row = (
            await db.execute(select(ModelPricing).where(ModelPricing.model == model))
        ).scalar_one_or_none()
        if row:
            row.input_price_per_1k = float(values["input_price_per_1k"])
            row.output_price_per_1k = float(values["output_price_per_1k"])
            row.currency = values.get("currency", "CNY")
        else:
            db.add(
                ModelPricing(
                    model=model,
                    input_price_per_1k=float(values["input_price_per_1k"]),
                    output_price_per_1k=float(values["output_price_per_1k"]),
                    currency=values.get("currency", "CNY"),
                )
            )

async def get_usage_summary(
    db: AsyncSession,
    user_id: str,
    session_id: str | None = None,
    days: int = 30,
) -> dict:
    cutoff = datetime.now() - timedelta(days=days)
    conds = [ModelTrace.user_id == user_id, ModelTrace.created_at >= cutoff]
    if session_id:
        conds.append(ModelTrace.session_id == session_id)

    total_row = (
        await db.execute(
            select(
                func.count(),
                func.coalesce(func.sum(ModelTrace.prompt_tokens), 0),
                func.coalesce(func.sum(ModelTrace.completion_tokens), 0),
                func.coalesce(func.avg(ModelTrace.latency_ms), 0),
            ).where(*conds)
        )
    ).one()
    total_calls = int(total_row[0] or 0)
    total_prompt = int(total_row[1] or 0)
    total_completion = int(total_row[2] or 0)
    avg_latency_ms = round(float(total_row[3] or 0), 1)

    stage_rows = (
        await db.execute(
            select(
                ModelTrace.stage,
                func.count(),
                func.coalesce(func.sum(ModelTrace.prompt_tokens), 0),
                func.coalesce(func.sum(ModelTrace.completion_tokens), 0),
            )
            .where(*conds)
            .group_by(ModelTrace.stage)
        )
    ).all()
    by_stage = [
        {
            "stage": stage,
            "calls": int(calls),
            "prompt_tokens": int(prompt_tok),
            "completion_tokens": int(comp_tok),
        }
        for stage, calls, prompt_tok, comp_tok in stage_rows
    ]

    model_rows = (
        await db.execute(
            select(
                ModelTrace.model,
                func.count(),
                func.coalesce(func.sum(ModelTrace.prompt_tokens), 0),
                func.coalesce(func.sum(ModelTrace.completion_tokens), 0),
            )
            .where(*conds)
            .group_by(ModelTrace.model)
        )
    ).all()
    prices = {
        item.model: item
        for item in (await db.execute(select(ModelPricing))).scalars().all()
    }
    total_cost = 0.0
    by_model = []
    for model, calls, prompt_tok, comp_tok in model_rows:
        price = prices.get(model)
        if price:
            cost = (
                float(prompt_tok) / 1000 * price.input_price_per_1k
                + float(comp_tok) / 1000 * price.output_price_per_1k
            )
        else:
            cost = 0.0
        total_cost += cost
        by_model.append({"model": model, "calls": int(calls), "cost_cny": round(cost, 6)})

    return {
        "days": days,
        "total_calls": total_calls,
        "total_prompt_tokens": total_prompt,
        "total_completion_tokens": total_completion,
        "total_tokens": total_prompt + total_completion,
        "total_cost_cny": round(total_cost, 6),
        "avg_latency_ms": avg_latency_ms,
        "by_stage": by_stage,
        "by_model": by_model,
    }

def hash_password(password: str) -> str:
    """对明文密码做 bcrypt 哈希，返回可直接存库的字符串。"""
    return bcrypt.hashpw(password.encode("utf-8"), bcrypt.gensalt()).decode("utf-8")

def verify_password(plain_password: str, hashed_password: str) -> bool:
    """校验明文密码与存储的哈希是否匹配；哈希格式非法时视为不匹配。"""
    try:
        return bcrypt.checkpw(
            plain_password.encode("utf-8"), hashed_password.encode("utf-8")
        )
    except ValueError:
        return False

def validate_password_strength(password: str) -> tuple[bool, str]:
    """密码强度策略：至少 8 位，且同时包含字母和数字。"""
    if len(password) < 8:
        return False, "密码长度至少 8 位"
    if not any(c.isalpha() for c in password):
        return False, "密码必须包含字母"
    if not any(c.isdigit() for c in password):
        return False, "密码必须包含数字"
    return True, ""

def _create_token(user_id: str, token_type: str, lifetime: timedelta) -> str:
    """签发 JWT；jti 唯一标识用于 Redis 白名单/黑名单。"""
    settings = get_settings()
    now = datetime.now(timezone.utc)
    payload = {
        "sub": user_id,
        "iat": now,
        "exp": now + lifetime,
        "jti": str(uuid.uuid4()),
        "type": token_type,
    }
    return jwt.encode(payload, settings.jwt_secret, algorithm=settings.jwt_algorithm)

def create_access_token(user_id: str) -> str:
    """签发短生命周期的 Access Token。"""
    settings = get_settings()
    return _create_token(
        user_id, "access", timedelta(minutes=settings.access_token_expire_minutes)
    )

def decode_token(token: str) -> dict:
    """解码并校验 JWT；过期与无效分别返回不同业务错误码。"""
    settings = get_settings()
    try:
        return jwt.decode(
            token, settings.jwt_secret, algorithms=[settings.jwt_algorithm]
        )
    except jwt.ExpiredSignatureError as exc:
        raise BusinessError(code=ErrorCode.TOKEN_EXPIRED, http_status=401) from exc
    except jwt.InvalidTokenError as exc:
        raise BusinessError(code=ErrorCode.TOKEN_INVALID, http_status=401) from exc

async def verify_refresh_token(user_id: str, jti: str) -> bool:
    """校验 Refresh Token 是否仍在白名单中（登出/轮换/改密后会移除）。"""
    return bool(await get_redis().get(_refresh_key(user_id, jti)))

async def revoke_all_refresh_tokens(user_id: str) -> None:
    """吊销某用户全部 Refresh Token（改密/全端登出场景）。"""
    redis = get_redis()
    cursor = 0
    while True:
        cursor, keys = await redis.scan(
            cursor, match=f"refresh_token:{user_id}:*", count=100
        )
        if keys:
            await redis.delete(*keys)
        if cursor == 0:
            break
    await _clear_all_device_sessions(user_id)

async def is_token_blacklisted(jti: str) -> bool:
    """检查 Access Token 是否已被登出拉黑。"""
    return bool(await get_redis().get(_blacklist_key(jti)))

async def get_current_token_payload(
    authorization: str | None = Header(default=None),
) -> dict:
    """解析 Bearer Token 并返回完整 payload。

    校验顺序：格式 → 签名/有效期 → 类型 → 黑名单（登出）。
    """
    if not authorization:
        raise BusinessError(
            code=ErrorCode.TOKEN_INVALID, message="缺少认证信息", http_status=401
        )

    parts = authorization.split()
    if len(parts) != 2 or parts[0].lower() != "bearer":
        raise BusinessError(
            code=ErrorCode.TOKEN_INVALID,
            message="Authorization 格式错误，应为 'Bearer <token>'",
            http_status=401,
        )

    payload = decode_token(parts[1])
    if payload.get("type") != "access":
        raise BusinessError(
            code=ErrorCode.TOKEN_INVALID, message="Token 类型错误", http_status=401
        )

    jti = payload.get("jti")
    if jti and await is_token_blacklisted(jti):
        raise BusinessError(
            code=ErrorCode.TOKEN_INVALID, message="Token 已被撤销", http_status=401
        )

    return payload

def remaining_ttl_seconds(payload: dict) -> int:
    """根据 payload 的 exp 计算剩余有效期（秒）。"""
    return int(payload["exp"] - time.time())

def parse_device_name(user_agent: str) -> str:
    """从 User-Agent 拼可读设备名，不引入额外依赖。"""
    if not user_agent:
        return "Unknown Device"

    os_name = "Unknown"
    if "Windows" in user_agent:
        os_name = "Windows"
    elif "Mac OS" in user_agent or "Macintosh" in user_agent:
        os_name = "macOS"
    elif "iPhone" in user_agent or "iPad" in user_agent:
        os_name = "iOS"
    elif "Android" in user_agent:
        os_name = "Android"
    elif "Linux" in user_agent:
        os_name = "Linux"

    browser = "Unknown"
    if "Edg" in user_agent:
        browser = "Edge"
    elif "Chrome" in user_agent and "Safari" in user_agent:
        browser = "Chrome"
    elif "Safari" in user_agent:
        browser = "Safari"
    elif "Firefox" in user_agent:
        browser = "Firefox"

    return f"{browser} / {os_name}"

def _client_ip(request: Request | None) -> str:
    if request is None:
        return ""
    forwarded = request.headers.get("X-Forwarded-For", "").split(",")[0].strip()
    if forwarded:
        return forwarded
    return request.client.host if request.client else ""

def infer_mime(filename: str, declared: str | None) -> str:
    ext = Path(filename).suffix.lower()
    if ext == ".markdown":
        ext = ".md"
    return declared or EXT_TO_MIME.get(ext, "application/octet-stream")

def calculate_md5_bytes(data: bytes) -> str:
    import hashlib

    return hashlib.md5(data).hexdigest()

def validate_upload_file(filename: str, file_size: int, max_size_mb: int = 50) -> str:
    """校验大小与扩展名，返回标准化扩展名（.pdf / .md / .txt）。"""
    max_size_bytes = max_size_mb * 1024 * 1024
    if file_size > max_size_bytes:
        raise BusinessError(
            code=ErrorCode.FILE_TOO_LARGE,
            detail=f"文件大小 {file_size / 1024 / 1024:.1f}MB 超过限制 {max_size_mb}MB",
        )

    ext = Path(filename or "").suffix.lower()
    if ext in FORBIDDEN_EXTENSIONS:
        raise BusinessError(
            code=ErrorCode.UNSUPPORTED_FILE_TYPE,
            detail=f"禁止上传 {ext} 类型的文件",
        )
    if ext == ".markdown":
        ext = ".md"
    if ext not in {".pdf", ".md", ".txt"}:
        raise BusinessError(
            code=ErrorCode.UNSUPPORTED_FILE_TYPE,
            detail=f"不支持的文件类型: {ext or '(无扩展名)'}，仅支持 PDF / Markdown / TXT",
        )
    return ext

async def read_upload_limited(file: UploadFile, max_size_mb: int) -> bytes:
    """分块读取，超过上限立即中断，避免超大文件打爆内存。"""
    max_size_bytes = max_size_mb * 1024 * 1024
    declared_size = getattr(file, "size", None)
    if declared_size is not None and declared_size > max_size_bytes:
        raise BusinessError(
            code=ErrorCode.FILE_TOO_LARGE,
            detail=f"文件大小 {declared_size / 1024 / 1024:.1f}MB 超过限制 {max_size_mb}MB",
        )

    content = bytearray()
    while True:
        chunk = await file.read(1024 * 1024)
        if not chunk:
            break
        content.extend(chunk)
        if len(content) > max_size_bytes:
            raise BusinessError(
                code=ErrorCode.FILE_TOO_LARGE,
                detail=f"文件超过大小限制 {max_size_mb}MB，已中断读取",
            )
    return bytes(content)

def _match_magic(content: bytes, signatures: list[tuple[int, bytes]]) -> bool:
    if not content:
        return False
    return all(
        content[offset : offset + len(magic)] == magic for offset, magic in signatures
    )

def validate_avatar_file(
    filename: str, file_size: int, content: bytes, max_size_mb: int = 5
) -> str:
    """校验头像：大小 + 扩展名白名单 + magic bytes。返回标准化扩展名。"""
    max_size_bytes = max_size_mb * 1024 * 1024
    if file_size > max_size_bytes:
        raise BusinessError(
            code=ErrorCode.FILE_TOO_LARGE,
            detail=f"头像文件大小 {file_size / 1024 / 1024:.1f}MB 超过限制 {max_size_mb}MB",
        )

    ext = Path(filename or "").suffix.lower()
    if ext == ".jpeg":
        ext = ".jpg"
    if ext not in AVATAR_MAGIC:
        raise BusinessError(
            code=ErrorCode.UNSUPPORTED_FILE_TYPE,
            detail=f"不支持的头像格式: {ext or '(无扩展名)'}，仅支持 PNG / JPG / WebP",
        )
    if not _match_magic(
        content, AVATAR_MAGIC[ext] if ext != ".jpg" else AVATAR_MAGIC[".jpg"]
    ):
        raise BusinessError(
            code=ErrorCode.UNSUPPORTED_FILE_TYPE,
            detail="文件内容与扩展名不符",
        )
    return ext

